begin;
-- Lecture des deux nouvelles sections : même stockage et mêmes restrictions.
create or replace function public.workshop_catalog_read107(p_section text,p_known integer default -1) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;v integer;manage boolean;begin
 a:=workshop_private.actor();perform workshop_private.assert_section('orders');
 if p_section not in ('Climatisation','Divers') then raise exception 'Section inconnue.';end if;
 manage:=coalesce((a->>'admin')::boolean,false) or coalesce((a->>'manager')::boolean,false);
 select rev into strict v from workshop_private.catalog75_rev where section=p_section;
 return jsonb_build_object('rev',v,'items',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'unavailable',c.unavailable,'managers_only',c.managers_only,'photo',case when c.photo is null then null else 'data:image/webp;base64,'||replace(encode(c.photo,'base64'),E'\n','') end) order by c.position,c.id),'[]') from workshop_private.catalog75 c where c.section=p_section and (manage or not c.managers_only)));
end $$;
create or replace function public.workshop_catalog_editor107(p_section text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;r jsonb;begin
 a:=workshop_private.actor();if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur.' using errcode='42501';end if;
 if p_section not in ('Climatisation','Divers') then raise exception 'Section inconnue.';end if;
 perform 1 from workshop_private.catalog75_rev where section=p_section for update;
 r:=public.workshop_catalog_read107(p_section,-1);
 return r||jsonb_build_object('token','107:'||(r->>'rev'),'codes',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'code',coalesce(pc.code,'')) order by c.position,c.id),'[]') from workshop_private.catalog75 c left join workshop_private.product_codes83 pc on pc.product_id=c.id where c.section=p_section));
end $$;
create or replace function public.workshop_catalog_editor106(p_section text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;r jsonb;begin
 a:=workshop_private.actor();if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur.' using errcode='42501';end if;
 perform 1 from workshop_private.catalog75_rev where section=p_section for update;
 if not found then raise exception 'Section introuvable.';end if;
 if p_section in ('Climatisation','Divers') then r:=public.workshop_catalog_editor107(p_section);else r:=public.workshop_catalog_editor89(p_section);end if;
 if jsonb_typeof(r->'items') is distinct from 'array' then raise exception 'Catalogue illisible.';end if;
 return jsonb_set(r,'{items}',(select coalesce(jsonb_agg(x.item||jsonb_build_object('edit_token106',workshop_private.catalog_token106(c.id)) order by x.ord),'[]'::jsonb)
 from jsonb_array_elements(r->'items') with ordinality x(item,ord) join workshop_private.catalog75 c on c.id::text=x.item->>'id' and c.section=p_section));
end $$;
revoke all on function public.workshop_catalog_editor106(text) from public,anon;
grant execute on function public.workshop_catalog_editor106(text) to authenticated;
CREATE OR REPLACE FUNCTION public.workshop_catalog_remove107(p_section text, p_id uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;n text;begin
 a:=workshop_private.actor();if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur' using errcode='42501';end if;
 if p_section not in ('Climatisation','Divers') then raise exception 'Section inconnue.';end if;
 perform 1 from workshop_private.catalog75_rev where section=p_section for update;
 select name into n from workshop_private.catalog75 where id=p_id and section=p_section for update;
 if not found then return;end if;
 if n is distinct from p_name then raise exception 'Cet article a été renommé. Rouvre le catalogue.';end if;
 update public.workshop_order_requests r set items=(select coalesce(jsonb_agg(i order by ord),'[]') from jsonb_array_elements(r.items) with ordinality q(i,ord)
 where not (coalesce(i->>'id','')=p_id::text or (coalesce(i->>'id','')<>p_id::text and (select count(*) from workshop_private.match_product79(i))=1 and exists(select 1 from workshop_private.match_product79(i) m where m.kind='catalog' and m.id=p_id::text)))),version=version+1,updated_at=now()
 where exists(select 1 from jsonb_array_elements(r.items) i where coalesce(i->>'id','')=p_id::text or ((select count(*) from workshop_private.match_product79(i))=1 and exists(select 1 from workshop_private.match_product79(i) m where m.kind='catalog' and m.id=p_id::text)));
 delete from workshop_private.catalog75 where id=p_id and section=p_section;
 update workshop_private.catalog75_rev set rev=rev+1 where section=p_section;end $function$
;
create or replace function public.workshop_catalog_publish107(p_section text,p_token text,p_changes jsonb) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;v integer;c jsonb;pid uuid;new_photo bytea;begin
 a:=workshop_private.actor();if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur.' using errcode='42501';end if;
 if p_section not in ('Climatisation','Divers') then raise exception 'Section inconnue.';end if;
 select rev into strict v from workshop_private.catalog75_rev where section=p_section for update;
 if p_token is distinct from '107:'||v then raise exception 'Le catalogue a changé. Rouvre l’import avant de publier.';end if;
 if jsonb_typeof(p_changes) is distinct from 'array' or jsonb_array_length(p_changes) not between 1 and 250 or octet_length(p_changes::text)>15000000 then raise exception 'Changements invalides.';end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  if coalesce(c->>'action','') not in ('save','delete') or length(btrim(coalesce(c->>'name',''))) not between 1 and 200 then raise exception 'Ligne invalide.';end if;
  pid:=nullif(c->>'id','')::uuid;
  if pid is not null and not exists(select 1 from workshop_private.catalog75 where id=pid and section=p_section) then raise exception 'Article introuvable.';end if;
  if c->>'action'='delete' then
   if pid is null then raise exception 'Article requis pour un retrait.';end if;
   perform public.workshop_catalog_remove107(p_section,pid,c->>'name');continue;
  end if;
  new_photo:=null;
  if c ? 'photo' then
   if c->>'photo' !~ '^data:image/webp;base64,[A-Za-z0-9+/=]+$' or length(c->>'photo')>500000 then raise exception 'Photo WebP invalide.';end if;
   new_photo:=decode(split_part(c->>'photo',',',2),'base64');
   if octet_length(new_photo)<12 or substring(new_photo from 1 for 4)<>decode('52494646','hex') or substring(new_photo from 9 for 4)<>decode('57454250','hex') then raise exception 'Photo WebP illisible.';end if;
  end if;
  if pid is null then
   if exists(select 1 from workshop_private.catalog75 where section=p_section and lower(btrim(name))=lower(btrim(c->>'name'))) then raise exception 'Cette désignation existe déjà. Associe la ligne à son article.';end if;
  else
   update workshop_private.catalog75 set name=btrim(c->>'name'),photo=coalesce(new_photo,workshop_private.catalog75.photo) where id=pid and section=p_section;
  end if;
 end loop;
 update workshop_private.catalog75_rev set rev=rev+1 where section=p_section;
end $$;
create or replace function public.workshop_settings103(p_settings jsonb default null,p_version integer default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;r workshop_private.settings81%rowtype;k text;v jsonb;next_settings jsonb;begin
 a:=workshop_private.actor_before30();
 if p_settings is null then select * into r from workshop_private.settings81 where id=1;return jsonb_build_object('settings',r.settings,'version',r.version);end if;
 if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur.' using errcode='42501';end if;
 select * into r from workshop_private.settings81 where id=1 for update;
 if not found or p_version is distinct from r.version then raise exception 'Les réglages ont changé. Ferme puis rouvre cet écran avant de réessayer.';end if;
 if jsonb_typeof(p_settings) is distinct from 'object' or jsonb_typeof(p_settings->'sections') is distinct from 'object' or jsonb_typeof(p_settings->'reminders') is distinct from 'object' then raise exception 'Réglages incomplets.';end if;
 for k,v in select * from jsonb_each(p_settings->'sections') loop
 if k not in ('journee','plan','tasks','reports','team','orders','waste','polls','recap','quality','disputes','settings','inbox','leave','lunch','skills','catalog.clim','catalog.divers','catalog.vidange','catalog.eclairage','catalog.oil','catalog.pneus','catalog.gaz','catalog.hygiene','catalog.freins','waste.Grandidier','waste.Chimirec','waste.Gurdebeke') then if v is distinct from r.settings->'sections'->k then raise exception 'Section inconnue : %',k;end if;continue;end if;
 if jsonb_typeof(v) is distinct from 'object' or jsonb_typeof(v->'title') is distinct from 'string' or length(btrim(v->>'title')) not between 1 and 90 or jsonb_typeof(v->'description') is distinct from 'string' or length(v->>'description')>300 then raise exception 'Nom ou description invalide pour la section %.',k;end if;
 end loop;
 for k,v in select * from jsonb_each(p_settings->'reminders') loop
 if k not in ('orders','waste') then if v is distinct from r.settings->'reminders'->k then raise exception 'Rappel inconnu.';end if;continue;end if;
 if jsonb_typeof(v) is distinct from 'object' or jsonb_typeof(v->'enabled') is distinct from 'boolean' or coalesce(v->>'mode','') not in ('weekly','once') or coalesce(v->>'weekday','') !~ '^[1-7]$' or coalesce(v->>'time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Paramètres de rappel invalides.';end if;
 if v->>'mode'='once' and (v->>'enabled')::boolean then
 if coalesce(v->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Date de rappel requise.';end if;
 perform (v->>'date')::date;end if;
 end loop;
 if not (p_settings->'reminders' ? 'orders') or not (p_settings->'reminders' ? 'waste') then raise exception 'Rappels incomplets.';end if;
 next_settings:=r.settings||jsonb_build_object('sections',p_settings->'sections','reminders',p_settings->'reminders');
 if next_settings is distinct from r.settings then update workshop_private.settings81 set settings=next_settings,version=version+1 where id=1 returning * into r;end if;
 return jsonb_build_object('settings',r.settings,'version',r.version);
end $$;
revoke all on function public.workshop_settings103(jsonb,integer) from public,anon;grant execute on function public.workshop_settings103(jsonb,integer) to authenticated;
create or replace function public.workshop_catalog_order107(p_order jsonb default null,p_version integer default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;r workshop_private.settings81%rowtype;known jsonb:='["Divers liquides","Pneus","5gaz","Freins, transmissions, roulements","Hygiène, protection et nettoyage","Vidange","Phare, ampoule, Pare brise, élec","Climatisation","Divers"]';begin
 a:=workshop_private.actor();if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur.' using errcode='42501';end if;
 select * into strict r from workshop_private.settings81 where id=1 for update;
 if p_order is not null then
  if p_version is distinct from r.version then raise exception 'Les réglages ont changé. Rouvre cet écran.';end if;
  if jsonb_typeof(p_order) is distinct from 'array' or jsonb_array_length(p_order)<>9 or (select count(distinct x) from jsonb_array_elements_text(p_order) x)<>9 or exists(select 1 from jsonb_array_elements(p_order) x where jsonb_typeof(x)<>'string' or not known @> jsonb_build_array(x)) then raise exception 'Ordre des catégories invalide.';end if;
  update workshop_private.settings81 set settings=jsonb_set(settings,'{catalog_order107}',p_order),version=version+1 where id=1 returning * into r;
 end if;
 return jsonb_build_object('settings',r.settings,'version',r.version,'order',coalesce(r.settings->'catalog_order107',known));
end $$;
revoke all on function public.workshop_catalog_read107(text,integer) from public,anon;grant execute on function public.workshop_catalog_read107(text,integer) to authenticated;
revoke all on function public.workshop_catalog_editor107(text) from public,anon;grant execute on function public.workshop_catalog_editor107(text) to authenticated;
revoke all on function public.workshop_catalog_remove107(text,uuid,text) from public,anon;grant execute on function public.workshop_catalog_remove107(text,uuid,text) to authenticated;
revoke all on function public.workshop_catalog_publish107(text,text,jsonb) from public,anon;grant execute on function public.workshop_catalog_publish107(text,text,jsonb) to authenticated;
revoke all on function public.workshop_catalog_order107(jsonb,integer) from public,anon;grant execute on function public.workshop_catalog_order107(jsonb,integer) to authenticated;
create table if not exists workshop_private.catalog_seed107(id integer primary key);
revoke all on workshop_private.catalog_seed107 from public,anon,authenticated;
do $seed$ begin if exists(select 1 from workshop_private.catalog_seed107 where id=1) then return;end if;
update workshop_private.catalog75_rev set rev=rev+1 where section in ('Climatisation','Divers');insert into workshop_private.catalog_seed107 values(1);end $seed$;
notify pgrst,'reload schema';commit;
